def get_all_mssn_seeds() -> List[MssnDemoSeedMeta]:
    return list(MSSN_SEEDS_CATALOG.values())


def get_mssn_seed(demo_id: str) -> Optional[MssnDemoSeedMeta]:
    return MSSN_SEEDS_CATALOG.get(demo_id.upper())
